// Sistema de buffer simple usando Static Data de N8N
// Agrupa mensajes enviados en ráfaga por el mismo usuario

const phoneNumber = $json.body.phoneNumber;
const textContent = $json.body.textContent;
const contactName = $json.body.contactName;
const phoneNumberId = $json.body.phoneNumberId;
const currentTime = Date.now();

// Obtener buffer existente del Static Data
const staticData = $getWorkflowStaticData('global');

if (!staticData.messageBuffers) {
  staticData.messageBuffers = {};
}

const bufferKey = 'buffer_' + phoneNumber;
const existingBuffer = staticData.messageBuffers[bufferKey];

if (existingBuffer && (currentTime - existingBuffer.timestamp) < 5000) {
  // Agregar mensaje al buffer existente
  existingBuffer.messages.push(textContent);
  existingBuffer.timestamp = currentTime;

  return {
    json: {
      action: 'wait',
      phoneNumber: phoneNumber,
      message: 'Mensaje agregado al buffer'
    }
  };
} else {
  // Crear nuevo buffer
  staticData.messageBuffers[bufferKey] = {
    messages: [textContent],
    timestamp: currentTime,
    phoneNumber: phoneNumber,
    contactName: contactName,
    phoneNumberId: phoneNumberId
  };

  return {
    json: {
      action: 'process',
      phoneNumber: phoneNumber,
      contactName: contactName,
      phoneNumberId: phoneNumberId,
      bufferKey: bufferKey
    }
  };
}

// Obtener y combinar todos los mensajes del buffer
const phoneNumber = $json.phoneNumber;
const contactName = $json.contactName;
const phoneNumberId = $json.phoneNumberId;
const bufferKey = $json.bufferKey;

const staticData = $getWorkflowStaticData('global');
const buffer = staticData.messageBuffers[bufferKey];

if (!buffer) {
  return {
    json: {
      error: 'Buffer not found',
      phoneNumber: phoneNumber
    }
  };
}

// Combinar todos los mensajes
const combinedMessage = buffer.messages.join(' ');
const messageCount = buffer.messages.length;

// Limpiar el buffer
delete staticData.messageBuffers[bufferKey];

return {
  json: {
    chatInput: combinedMessage,
    sessionId: phoneNumber,
    phoneNumber: phoneNumber,
    contactName: contactName,
    phoneNumberId: phoneNumberId,
    messageCount: messageCount
  }
};

// Detectar acciones especiales en la respuesta
const output = $json.output;
const phoneNumber = $node['Prepare for Agent'].json.phoneNumber;
const phoneNumberId = $node['Prepare for Agent'].json.phoneNumberId;
const contactName = $node['Prepare for Agent'].json.contactName;

let action = 'send_text';
let cleanMessage = output;

// Detectar acciones especiales
if (output.includes('<<ACTION:SHOW_CALENDAR>>')) {
  action = 'show_calendar';
  cleanMessage = output.replace('<<ACTION:SHOW_CALENDAR>>', '').trim();
} else if (output.includes('<<ACTION:CANCEL_APPOINTMENT>>')) {
  action = 'cancel_appointment';
  cleanMessage = output.replace('<<ACTION:CANCEL_APPOINTMENT>>', '').trim();
} else if (output.includes('<<ACTION:RESCHEDULE_APPOINTMENT>>')) {
  action = 'reschedule_appointment';
  cleanMessage = output.replace('<<ACTION:RESCHEDULE_APPOINTMENT>>', '').trim();
} else if (output.includes('<<ACTION:ESCALATE_SUPPORT>>')) {
  action = 'escalate_support';
  cleanMessage = output.replace('<<ACTION:ESCALATE_SUPPORT>>', '').trim();
}

return {
  json: {
    action: action,
    message: cleanMessage,
    phoneNumber: phoneNumber,
    phoneNumberId: phoneNumberId,
    contactName: contactName
  }
};

